  const pctSeisMeses = Math.round(100 * mesesEstadias.filter(n =&gt; n &gt;= 6).length / mesesEstadias.length);
  const cid = cidadesNatal.cidades;
  const areasContadas = [...historicoArea.values()].map(h =&gt; ({ nome: h.nome,
    n: new Set([...h.duplas.values()].flatMap(d =&gt; d.dupla.map(chavePessoa))).size }));
  const maxArea = Math.max(0, ...areasContadas.map(a =&gt; a.n));
  const areasTop = areasContadas.filter(a =&gt; a.n === maxArea).map(a =&gt; a.nome).sort((a, b) =&gt; a.localeCompare(b, "pt"));
  // All 36 full months, including months with no recorded arrivals or departures.
  const movimento = Array.from({ length: 36 }, (_, i) =&gt; {
    const ano = 1997 + Math.floor((i + 6) / 12), mes = (i + 6) % 12 + 1;
    const chegadas = conta(m =&gt; m.ChegadaAno === ano && m["ChegadaMês"] === mes);
    const saidas = conta(m =&gt; m["SaídaAno"] === ano && m["SaídaMês"] === mes);
    return { ano, mes, chegadas, saidas, total: chegadas + saidas };
  });
  const maxMovimento = Math.max(...movimento.map(m =&gt; m.total));
  const minMovimento = Math.min(...movimento.map(m =&gt; m.total));
  const detalheMovimento = total =&gt; movimento.filter(m =&gt; m.total === total).map(m =&gt; htl.html`&lt;div&gt;${fmtMesAno(m)}&lt;br&gt;${m.chegadas} ${T(m.chegadas === 1 ? "chegada" : "chegadas", m.chegadas === 1 ? "arrival" : "arrivals")} + ${m.saidas} ${T(m.saidas === 1 ? "saída" : "saídas", m.saidas === 1 ? "departure" : "departures")}&lt;/div&gt;`);
  const estados = p =&gt; new Set(cid.filter(c =&gt; c.pais === p).map(c =&gt; c.estado));
  const topBR = cid.filter(c =&gt; c.pais === "BR").sort((a, b) =&gt; b.n - a.n)[0];
  const topUS = cid.filter(c =&gt; c.pais === "US").sort((a, b) =&gt; b.n - a.n)[0];
  const sobrenomeTop = nacionalidade =&gt; {
    const grupos = new Map();
    for (const m of missionaries.filter(m =&gt; m.Nacionalidade === nacionalidade)) {
      const nome = m.Plaqueta.trim().replace(/^(?:[A-Z]\.?\s+)+/, "").replace(/^(?:(?:da|de|do|das|dos)\s+)+/i, "");
      const k = norm(nome);
      if (!grupos.has(k)) grupos.set(k, { nome, n: 0 });
      grupos.get(k).n++;
    }
    const max = Math.max(...[...grupos.values()].map(g =&gt; g.n));
    const nomes = [...grupos.values()].filter(g =&gt; g.n === max).map(g =&gt; g.nome).sort().join(" / ");
    return htl.html`&lt;span&gt;${T("Sobrenome mais comum", "Most common surname")}&lt;br&gt;&lt;strong&gt;${nomes}&lt;/strong&gt;&lt;br&gt;${T(`${max} por sobrenome`, `${max} per surname`)}&lt;/span&gt;`;
  };
  const detalheEstados = pais =&gt; {
    const nomes = { SP: "São Paulo", BA: "Bahia", RJ: "Rio de Janeiro", UT: "Utah", ID: "Idaho", CA: T("Califórnia", "California") };
    const totais = new Map();
    for (const c of cid.filter(c =&gt; c.pais === pais)) totais.set(c.estado, (totais.get(c.estado) ?? 0) + c.n);
    return [...totais].sort((a, b) =&gt; b[1] - a[1]).slice(0, 3).map(([uf, n]) =&gt; htl.html`&lt;span class="stat-detail-line"&gt;${nomes[uf] ?? uf} · ${n}&lt;/span&gt;`);
  };
  const tile = (num, lbl, detalhe = null) =&gt; {
    if (detalhe === null) return htl.html`&lt;div class="stat-tile"&gt;&lt;div class="num"&gt;${num}&lt;/div&gt;&lt;div class="lbl"&gt;${lbl}&lt;/div&gt;&lt;/div&gt;`;
    const frente = htl.html`&lt;span class="stat-face stat-front"&gt;&lt;span class="num"&gt;${num}&lt;/span&gt;&lt;span class="lbl"&gt;${lbl}&lt;/span&gt;&lt;/span&gt;`;
    const verso = htl.html`&lt;span class="stat-face stat-back" aria-hidden="true"&gt;&lt;span class="stat-detail"&gt;${detalhe}&lt;/span&gt;&lt;/span&gt;`;
    const botao = htl.html`&lt;button type="button" class="stat-tile stat-flip" aria-pressed="false" title=${T("Toque para virar", "Click to flip")}&gt;&lt;span class="stat-flip-inner"&gt;${frente}${verso}&lt;/span&gt;&lt;i class="bi bi-arrow-repeat stat-flip-hint" aria-hidden="true"&gt;&lt;/i&gt;&lt;/button&gt;`;
    botao.addEventListener("click", () =&gt; {
      const virado = botao.classList.toggle("is-flipped");
      botao.setAttribute("aria-pressed", String(virado));
      frente.setAttribute("aria-hidden", String(virado));
      verso.setAttribute("aria-hidden", String(!virado));
    });
    return botao;
  };
  return htl.html`&lt;div class="stat-tiles numeros"&gt;
      ${tile(conta(m =&gt; m["Título"] === "Élder"), T("élderes", "elders"), htl.html`&lt;span&gt;${conta(m =&gt; m["Título"] === "Élder" && m.Nacionalidade === "norte americano")} ${T("norte-americanos", "North Americans")}&lt;br&gt;${conta(m =&gt; m["Título"] === "Élder" && m.Nacionalidade === "brasileiro")} ${T("brasileiros", "Brazilians")}&lt;/span&gt;`)}
      ${tile(conta(m =&gt; m["Título"] === "Síster"), T("sísteres", "sisters"), htl.html`&lt;span&gt;${conta(m =&gt; m["Título"] === "Síster" && m.Nacionalidade === "norte americano")} ${T("norte-americanas", "North Americans")}&lt;br&gt;${conta(m =&gt; m["Título"] === "Síster" && m.Nacionalidade === "brasileiro")} ${T("brasileiras", "Brazilians")}&lt;/span&gt;`)}
      ${tile(conta(m =&gt; m.Nacionalidade === "brasileiro"), T("brasileiros", "Brazilians"), sobrenomeTop("brasileiro"))}
      ${tile(conta(m =&gt; m.Nacionalidade === "norte americano"), T("norte-americanos", "North Americans"), sobrenomeTop("norte americano"))}
      ${tile(fmtNum(mediaArea), T("meses, em média, numa mesma área", "months: average stay in one area"), htl.html`&lt;span&gt;&lt;strong&gt;${pctSeisMeses}%&lt;/strong&gt;&lt;br&gt;${T("das estadias registradas duraram seis meses ou mais", "of recorded stays lasted six months or more")}&lt;/span&gt;`)}
      ${tile(Math.round(mediaComp), T("companheiros, em média, por missão", "companions: average per mission"), htl.html`&lt;span&gt;${T("Metade dos missionários teve pelo menos", "Half of missionaries had at least")} &lt;strong&gt;${fmtNum(medianaComp)}&lt;/strong&gt; ${T("companheiros registrados", "recorded companions")}&lt;/span&gt;`)}
      ${tile(cid.length, T("cidades de origem", "hometowns"), htl.html`&lt;span&gt;${T("Maiores grupos", "Largest groups")}&lt;br&gt;${topBR.cidade} · ${topBR.n}&lt;br&gt;${topUS.cidade} · ${topUS.n}&lt;/span&gt;`)}
