      ${tile(estados("US").size, T("estados americanos", "U.S. states"), detalheEstados("US"))}
      ${tile(maxArea, T("missionários na área mais frequentada", "missionaries in the most-served area"), areasTop.join(" / "))}
      ${tile(maxMovimento, T("mais chegadas e saídas no mês", "most arrivals and departures in a month"), detalheMovimento(maxMovimento))}
      ${tile(minMovimento, T("menos chegadas e saídas no mês", "fewest arrivals and departures in a month"), detalheMovimento(minMovimento))}
