Siga a jornada de um missionárioFollow a missionary’s journey

Digite um sobrenome e toque no nome para ver a jornada do missionário no mapa: o nome sai do escritório da missão em Porto Alegre, passa pelas áreas dos quadros de transferências e volta a Porto Alegre no fim da missão. Abaixo do mapa ficam o itinerário e todos os quadros e companheiros.Type a last name and tap the name to see that missionary’s journey on the map: the name leaves the mission office in Porto Alegre, moves through the areas on the transfer boards and returns to Porto Alegre at the end of the mission. Below the map are the itinerary and every board and companion.


viewof jornadaModo = estado({ tipo: "nenhum", auto: false })
seguirPessoa = chave =&gt; {
  definir(viewof jornadaModo, { tipo: "pessoa", chave, auto: true });
  setTimeout(() =&gt; document.getElementById("mapa-jornada")?.scrollIntoView({ behavior: "smooth", block: "center" }), 50);
}
chaveMes = (a, m) =&gt; `${a}-${String(m).padStart(2, "0")}`
mesAntes = k =&gt; { let [y, m] = k.split("-").map(Number); if (--m === 0) { m = 12; y--; } return chaveMes(y, m); }
mesDepois = k =&gt; { let [y, m] = k.split("-").map(Number); if (++m === 13) { m = 1; y++; } return chaveMes(y, m); }

jornadaLista = {
  if (jornadaModo.tipo === "pessoa") {
    const x = pessoas.get(jornadaModo.chave) ?? null;
    return [{ chave: jornadaModo.chave, x, nome: x ? `${x.titulo} ${x.plaqueta}` : nomeCompleto(jornadaModo.chave.slice(1)) }];
  }
  return [];
}

// A missionary's stops, month by month: the mission office at arrival, every área on the boards,
// and the office again at departure. Someone who drops off the boards before leaving (for example,
// the zones that went to the Santa Maria mission in July 1998) fades out instead of returning.
trajetoJornada = (chave, x) =&gt; {
  const ap = aparicoes.get(chave) ?? [];
  if (!ap.length) return null;
  const pri = ap[0].key, ult = ap.at(-1).key, ultSnap = snaps.at(-1).key;
  // Keys are "YYYY-MM|n" so an arrival (0), a board (1) and a departure (2) can share a month.
  // Missionaries who arrived before the first board (October 1997) have no known first areas:
  // they start at their first área on the boards instead of at the office.
  const parcial = !x?.chegada || x.chegada &lt; snaps[0].key;
  const ev = parcial ? [] : [{ key: `${x.chegada &lt;= pri ? x.chegada : mesAntes(pri)}|0`, pos: ESCRITORIO, tipo: "chegada" }];
  for (const a of ap) {
    const c = a.especial || !a.areaNome ? null : areaCoord(a.areaNome, a.zona);
    const pos = c ? [c.lat, c.lon] : a.especial ? ESCRITORIO : (ZONA_POS[a.zona] ?? ev.at(-1)?.pos ?? ESCRITORIO);
    ev.push({ key: `${a.key}|1`, pos, tipo: "area", area: a.especial ? a.zona : a.area, zona: a.zona, aprox: c?.fonte === "aproximado",
      fotoArea: !a.especial && a.areaNome ? chaveArea(a.areaNome, a.zona) : null,
      companheiros: a.companheiros.map(p =&gt; nomeCompleto(p.n)) });
  }
  const sumiu = snaps.find(s =&gt; s.key &gt; ult && (!x?.saida || s.key &lt; x.saida));
  if (sumiu) {
    const santaMaria = ["Ijuí", "Santo Ângelo"].includes(ap.at(-1).zona) && ult &lt; DIVISAO;
    ev.push({ key: `${sumiu.key}|1`, pos: ev.at(-1).pos, tipo: "fim", santaMaria });
  } else if (x?.saida && x.saida &lt;= mesDepois(ultSnap)) {
    ev.push({ key: `${x.saida &gt;= ult ? x.saida : mesDepois(ult)}|2`, pos: ESCRITORIO, tipo: "saida" });
  } else if (ult === ultSnap) {
    // Still serving when the Woodwards left (July 2000): the boards end, so they stay at their last área.
    ev.push({ key: `${mesDepois(ultSnap)}|1`, pos: ev.at(-1).pos, tipo: "continua", ate: x?.saida ?? null });
  }
  ev.parcial = parcial;
  return ev;
}



















































