  };
  const botaoPlay = htl.html`&lt;button class="jornada-play" aria-label=${T("Tocar", "Play")}&gt;&lt;i class="bi bi-play-fill"&gt;&lt;/i&gt;&lt;/button&gt;`;
  const marcarBotao = () =&gt; {
    botaoPlay.innerHTML = tocando ? '&lt;i class="bi bi-pause-fill"&gt;&lt;/i&gt;' : t &gt;= total ? '&lt;i class="bi bi-arrow-counterclockwise"&gt;&lt;/i&gt;' : '&lt;i class="bi bi-play-fill"&gt;&lt;/i&gt;';
