  const assinatura = jornadaModo.tipo + "|" + viagens.map(v =&gt; v.chave).join(",");
  const salvo = el.salvo?.assinatura === assinatura && el.salvo.modo === jornadaModo ? el.salvo : null;
  invalidation.then(() =&gt; { el.salvo = { assinatura, modo: jornadaModo, t, tocando: tocando || timer !== null }; tocando = false; cancelAnimationFrame(raf); clearTimeout(timer); });

  const caixa = htl.html`&lt;div class="jornada-controle"&gt;${botaoPlay}&lt;div class="jornada-rotulos"&gt;${rotuloMes}${rotuloMarco}&lt;/div&gt;&lt;/div&gt;`;
  L.DomEvent.disableClickPropagation(caixa);
  el.controle = new (L.Control.extend({ onAdd: () =&gt; caixa }))({ position: "topright" }).addTo(m);

  const legenda = htl.html`&lt;div class="jornada-legenda"&gt;${viagens.length &gt; 1 ? viagens.map(v =&gt; htl.html`&lt;button class="chip jornada-chip" style=${`--c:${v.cor}`} title=${T("Seguir só este missionário", "Follow just this missionary")} onmouseenter=${() =&gt; { foco = v; aplicarFoco(); }} onmouseleave=${() =&gt; { foco = null; aplicarFoco(); }} onclick=${() =&gt; seguirPessoa(v.chave)}&gt;${v.nome}${v.ev.parcial ? htl.html` &lt;span class="parcial"&gt;${T(`desde ${fmtYM(snaps[0].key)}`, `from ${fmtYM(snaps[0].key)}`)}&lt;/span&gt;` : ""}${v.ev.at(-1).tipo === "continua" ? htl.html` &lt;span class="parcial"&gt;${v.ev.at(-1).ate ? T(`até ${fmtYM(v.ev.at(-1).ate)}`, `until ${fmtYM(v.ev.at(-1).ate)}`) : T("continuou", "stayed on")}&lt;/span&gt;` : ""}&lt;/button&gt;`) : ""}&lt;/div&gt;`;
  aplicarFoco();
