    }, 180);
    legenda.textContent = T(f.pt, f.en);
    const ondeLink = htl.html`&lt;a href=${f.onde[0]} onclick=${() =&gt; {
      if (f.secao === "missionarios" && f.mes) { const [a, m] = f.mes.split("-").map(Number); definir(viewof mesSel, m); definir(viewof anoSel, a); }
    }}&gt;${T("Ver no site: ", "See it on the site: ")}${T(f.onde[1], f.onde[2])}&lt;/a&gt;`;
    credito.replaceChildren(
      f.link ? htl.html`&lt;a href=${f.link} target="_blank" rel="noopener"&gt;${T(f.credito[0], f.credito[1])}&lt;/a&gt;` : T(f.credito[0], f.credito[1]),
      " · ", ondeLink);
    contador.textContent = `${ordemFotos.atual + 1} ${T("de", "of")} ${n}`;
    pre.src = fotos[(ordemFotos.atual + 1) % n].src;
  };
  const agendar = () =&gt; { clearTimeout(timer); if (tocando && visivel) timer = setTimeout(() =&gt; { mostrar(ordemFotos.atual + 1); agendar(); }, INTERVALO); };
  const marcarPlay = () =&gt; {
    botaoPlay.innerHTML = tocando ? '&lt;i class="bi bi-pause-fill"&gt;&lt;/i&gt;' : '&lt;i class="bi bi-play-fill"&gt;&lt;/i&gt;';
    botaoPlay.setAttribute("aria-label", tocando ? T("Pausar", "Pause") : T("Tocar", "Play"));
  };
  botaoPlay.onclick = () =&gt; { tocando = !tocando; marcarPlay(); agendar(); };
  const ir = d =&gt; () =&gt; { mostrar(ordemFotos.atual + d); agendar(); };
  const obs = new IntersectionObserver(es =&gt; { visivel = es[0].isIntersecting; agendar(); }, { threshold: 0.3 });
  const caixa = htl.html`&lt;div class="fotos-show"&gt;
    &lt;div class="fotos-palco"&gt;
      ${img}
      &lt;button class="fotos-seta fotos-ant" aria-label=${T("Foto anterior", "Previous photo")} onclick=${ir(-1)}&gt;&lt;i class="bi bi-chevron-left"&gt;&lt;/i&gt;&lt;/button&gt;
      &lt;button class="fotos-seta fotos-prox" aria-label=${T("Próxima foto", "Next photo")} onclick=${ir(1)}&gt;&lt;i class="bi bi-chevron-right"&gt;&lt;/i&gt;&lt;/button&gt;
    &lt;/div&gt;
    &lt;div class="fotos-info"&gt;${legenda}${credito}&lt;/div&gt;
    &lt;div class="fotos-controles"&gt;${botaoPlay}${contador}&lt;/div&gt;
  &lt;/div&gt;`;
  obs.observe(caixa);
  invalidation.then(() =&gt; { clearTimeout(timer); obs.disconnect(); });
  marcarPlay();
  mostrar(ordemFotos.atual);
  return caixa;
}

