historiasDados = FileAttachment("data/historias.json").json()







// Stories from historias/*.md: a card per story that opens to read.
{
  const l = historiasDados.historias;
  const corpo = h =&gt; htl.html`&lt;div class="historia-texto" lang=${h.idioma}&gt;${h.paragrafos.map(p =&gt; { const el = htl.html`&lt;p&gt;&lt;/p&gt;`; el.innerHTML = p; return el; })}&lt;/div&gt;`;
  const meta = h =&gt; [h.autor, h.area, h.ano].filter(Boolean).join(" · ");
  const outraLingua = h =&gt; (idioma === "en" && h.idioma === "pt") ? " (in Portuguese)" : (idioma === "pt" && h.idioma === "en") ? " (em inglês)" : "";
  return l.length
    ? htl.html`&lt;div class="historias-lista"&gt;${l.map(h =&gt; htl.html`&lt;details class="historia"&gt;
        &lt;summary&gt;&lt;span class="historia-titulo"&gt;${h.titulo}&lt;/span&gt;&lt;span class="historia-meta"&gt;${meta(h)}${outraLingua(h)}&lt;/span&gt;&lt;/summary&gt;
        ${corpo(h)}
      &lt;/details&gt;`)}&lt;/div&gt;`
    : htl.html`&lt;p class="historias-vazio"&gt;${T("Ainda não há histórias publicadas. Que tal mandar a primeira?", "No stories yet. Why not send the first one?")}&lt;/p&gt;`;
